usage:
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Images.Variations.New(
		context.TODO(),
		openai.ImageVariationNewParams{
			Image: io.Reader(bytes.NewBuffer([]byte("Example data"))),
			Model: "string",
			N: param.NewOpt[int64](1),
			ResponseFormat: openai.CreateImageVariationRequestResponseFormatURL,
			Size: openai.CreateImageVariationRequestSize256x256,
			User: param.NewOpt[string]("string"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
